"""Writes cmds.pyi from the live command registry so editors and basedpyright see typed commands."""

import os

import _lila

_TYPES = {"bool": "bool", "int": "int", "float": "float", "str": "str", "tuple[float, float, float]": "Sequence[float]", "list": "Sequence[Any]"}


def _render():
    lines = [
        "# Generated by Lila from the command registry. Do not edit.",
        "from typing import Any, Sequence",
        "",
    ]
    for spec in sorted(_lila.commands(), key=lambda s: s["name"]):
        params = ["*objects: Any"] if spec["positional"] else []
        for f in spec["flags"]:
            t = _TYPES.get(f["type"], "Any")
            params.append(f"{f['name']}: {t} | None = None")
        doc = spec["doc"].replace('"""', "'''")
        lines.append(f"def {spec['name']}({', '.join(params)}) -> Any:")
        lines.append(f'    """{doc}"""')
        lines.append("")
    lines.append("def refresh() -> None: ...")
    lines.append("")
    return "\n".join(lines)


def write(force=False):
    """Rewrites the stub only when the registry changed. Silently skips read-only installs."""
    path = os.path.join(os.path.dirname(__file__), "cmds.pyi")
    text = _render()
    try:
        if not force and os.path.isfile(path):
            with open(path, encoding="utf-8") as f:
                if f.read() == text:
                    return path
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
    except OSError:
        return None
    return path
